		if (isEmpty()) throw new RuntimeException("empty tree");

		Node aux = root;
        String out = "";
		while (aux.left != null) {
            out += aux.value + " ";
			aux = aux.left;
        }
		System.out.println(out + aux.value);
		return aux.value;

	}

	public int max() {

		if (isEmpty()) throw new RuntimeException("empty tree");

		Node aux = root;
        String out = "";
		while (aux.right != null) {
            out += aux.value + " ";
			aux = aux.right;
        }
		System.out.println(out + aux.value);
		return aux.value;

	}





	public int sum() {
		return sum(this.root);
	}

