		for (int j = 1; j < array.length; j++) {
			if (array[j] < pivot) {
				index_pivot+=1;
				swap(array,index_pivot,j);
			}
		}
		return index_pivot;
	}

	private static void swap(int[] array, int i, int j) {
		int aux = array[i];
		array[i] = array[j];
		array[j] = aux;
	}

