        if (this.isFull())
            return false;

        if (this.isEmpty()) {
            this.head = 0;
            this.tail = 0;
            this.fila[head] = n;
        } else {
            this.tail = (this.tail + 1) % capacidade;
            this.fila[tail] = n;
        }
        return true; 
    }

    public boolean remove() {
        if (isEmpty()) return false;

        if (head == tail) {
            int out = this.fila[head];
            this.head = -1;
            this.tail = -1;
            return true;
        } else {
            this.head = (this.head + 1) % capacidade;
            return true;

        }
    }

